&lt;li style=&quot;line-height: 121%;&quot;&gt;&lt;span style=&quot;line-height: 121%;&quot;&gt; &lt;&sol;span&gt;&lt;span style=&quot;line-height: 121%;&quot;&gt;To assess for possible drug-drug interactions;&lt;&sol;span&gt;&lt;&sol;li&gt;
&lt;li style=&quot;line-height: 121%;&quot;&gt;&lt;span style=&quot;line-height: 121%;&quot;&gt; &lt;&sol;span&gt;&lt;span style=&quot;line-height: 121%;&quot;&gt;Change in patient&amp;rsquo;s medical condition or behavior;&lt;&sol;span&gt;&lt;&sol;li&gt;
