&lt;td style=&quot;width: 44.2807%;&quot;&gt;&lt;span style=&quot;line-height: 107%;&quot;&gt;25-49%&lt;&sol;span&gt;&lt;&sol;td&gt;
&lt;td style=&quot;width: 35.6791%;&quot;&gt;&lt;span style=&quot;line-height: 107%;&quot;&gt;Mild non-obstructive CAD&lt;&sol;span&gt;&lt;&sol;td&gt;
&lt;&sol;tr&gt;
