&lt;td style=&quot;width: 19.9333%;&quot;&gt;&lt;span style=&quot;line-height: 107%;&quot;&gt;CAD-RADS 3&lt;&sol;span&gt;&lt;&sol;td&gt;
&lt;td style=&quot;width: 44.2807%;&quot;&gt;&lt;span style=&quot;line-height: 107%;&quot;&gt;50-69%&lt;&sol;span&gt;&lt;&sol;td&gt;
&lt;td style=&quot;width: 35.6791%;&quot;&gt;&lt;span style=&quot;line-height: 107%;&quot;&gt;Moderate stenosis&lt;&sol;span&gt;&lt;&sol;td&gt;
&lt;&sol;tr&gt;
