&lt;td style=&quot;width: 19.9333%;&quot;&gt;&lt;span style=&quot;line-height: 107%;&quot;&gt;CAD-RADS 4&lt;&sol;span&gt;&lt;&sol;td&gt;
&lt;td style=&quot;width: 44.2807%;&quot;&gt;&lt;span style=&quot;line-height: 107%;&quot;&gt;70-99% or left main &amp;ge;50% or 3-vessel obstructive (&amp;ge;70%) disease&lt;&sol;span&gt;&lt;&sol;td&gt;
&lt;td style=&quot;width: 35.6791%;&quot;&gt;&lt;span style=&quot;line-height: 107%;&quot;&gt;Severe stenosis&lt;&sol;span&gt;&lt;&sol;td&gt;
