&lt;td style=&quot;width: 2.45in; border-top: none; border-left: none; border-bottom: solid windowtext 1.0pt; border-right: solid windowtext 1.0pt; padding: 0in 5.4pt 0in 5.4pt;&quot; width=&quot;235&quot;&gt;
