&lt;p&gt;&lt;span style=&quot;font-family: &#39;Verdana&#39;,&#39;sans-serif&#39;; font-size: 10.5pt; mso-bidi-font-family: Arial; mso-fareast-font-family: Verdana;&quot;&gt;42 CFR &amp;sect;&lt;&sol;span&gt;&lt;span style=&quot;font-family: &#39;Verdana&#39;,&#39;sans-serif&#39;; font-size: 10.5pt; mso-bidi-font-family: Arial; mso-fareast-font-family: Verdana;&quot;&gt;494.90 Condition: Patient plan of care&lt;&sol;span&gt;&lt;&sol;p&gt;
